'use strict';
const COMBAT_STANCES={normal:{name:'기본',icon:'◌',help:'캐릭터의 고유 AI로 판단합니다.'},cautious:{name:'신중함',icon:'🛡️',help:'접근하는 적과 거리를 벌리고, 공격이 끝난 빈틈에 반격 후 이탈합니다. 공격력 −20%, 추가 회피 10%. 패링 성공률 +25%(최대 100%), 타이밍 실수 확률 15%.'},rush:{name:'저돌적',icon:'⚔️',help:'관망 없이 진입. 공격력 +25%, 받는 피해 +20%. 탄도 감지와 확률 회피 감소.'},cover:{name:'엄호',icon:'🤝',help:'가까이 배치된 아군을 따라붙으며 적·투사체와 아군 사이를 가로막습니다. 공격력 −15%, 방어력 +15%.'}};
const STRATEGY_CARDS=[
 {kind:'mango',name:'망고주스',icon:'🥭',help:'최대 HP의 30% 회복',cost:70,usage:'once',rule:'일회성 · 사용 후 사라짐'},
 {kind:'evade',name:'전투회피',icon:'💨',help:'재개 즉시 탈출 대시 후 안전한 곳으로 6초간 도주',cost:140,usage:'floor',rule:'층당 1회'},
 {kind:'charge',name:'충전',icon:'⚡',help:'궁극기 게이지 +50%p',cost:170,usage:'cooldown',rule:'사용 후 두 층을 지나 재사용'},
 {kind:'shield',name:'보호막',icon:'🫧',help:'8초간 피해 100을 흡수하는 보호막',cost:120,usage:'once',rule:'일회성 · 사용 후 사라짐'},
 {kind:'iron',name:'철벽방어',icon:'🏰',help:'패링 즉시 준비 · 15초간 패링 쿨타임 3초',cost:220,usage:'cooldown',rule:'사용 후 두 층을 지나 재사용'},
 {kind:'taunt',name:'도발',icon:'📣',help:'가까운 적 2명이 8초간 나를 공격',cost:160,usage:'floor',rule:'층당 1회'}
];
const TURNING_FIRST=12,TURNING_INTERVAL=30,TURNING_DURATION=40,TURNING_BRAKE=2;
let turning={enabled:false,phase:'idle',nextAt:TURNING_FIRST,brake:0,remaining:0,selectedId:null,selectedCard:null,forecasts:[],serial:0},strategyUnitId=null,unitStrategyTab='stance',customItemSelection=null,strategyDrag=null,suppressStrategyClickUntil=0,strategyTouch=null,deploymentStrategyPress=null;
function setupBattleStrategies(){for(const u of units){u.strategyBaseDamage=u.dmg;u.combatStance=COMBAT_STANCES[u.stance]?u.stance:'normal';u.coverAnchor={x:u.x,y:u.y};u.coverAllyId=null;u.commandRetreatUntil=0;u.tauntedUntil=0;u.focusUntil=0;u.strategySpecialUntil=0;applyStanceStats(u);bindCoverAlly(u);if(gameKind==='tower')restoreTowerStrategyState(u);}}
function applyStanceStats(u){u.dmg=u.strategyBaseDamage*stanceAttackFactor(u)*(u.strategySpecialUntil>elapsed?1.25:1);}
function bindCoverAlly(u){const friends=units.filter(v=>v.id!==u.id&&v.hp>0&&v.faction===u.faction);const start=roster.find(p=>p.id===u.id)??u;u.coverAllyId=friends.sort((a,b)=>dist(start,roster.find(p=>p.id===a.id)??a)-dist(start,roster.find(p=>p.id===b.id)??b))[0]?.id??null;}
function stanceButtons(current,attribute){return Object.entries(COMBAT_STANCES).map(([id,s])=>`<button ${attribute}="${id}" aria-pressed="${current===id}" title="${s.help}">${s.icon} ${s.name}</button>`).join('');}
function openUnitStrategy(id){const p=roster.find(p=>p.id===id);if(!p||!['setup','towerSetup'].includes(screen))return false;if(gameKind==='tower'&&!p.towerAlly){openCharacterInfo(p.type,p);return false;}strategyUnitId=id;unitStrategyTab='stance';customItemSelection=null;deploymentStrategyPress=null;renderUnitStrategy();$('unitStrategy').showModal();return true;}
function customEquippedItems(p){return (Array.isArray(p?.customItems)?p.customItems:[]).map(kind=>TOWER_ITEMS.find(item=>item.id===kind&&!item.consumable)).filter(Boolean).slice(0,TOWER_MAX_EQUIPMENT);}
function canEditCustomEquipment(p){return !!p&&gameKind==='custom'&&screen==='setup'&&!p.towerAlly&&!p.towerEnemy;}
function equipCustomItem(id,kind){
 const p=roster.find(p=>p.id===id),item=TOWER_ITEMS.find(item=>item.id===kind&&!item.consumable);if(!canEditCustomEquipment(p)||!item)return false;
 const items=customEquippedItems(p);if(items.length>=TOWER_MAX_EQUIPMENT)return false;p.customItems=[...items.map(item=>item.id),kind];return true;
}
function removeCustomItem(id,index){
 const p=roster.find(p=>p.id===id),items=customEquippedItems(p);if(!canEditCustomEquipment(p)||!Number.isInteger(index)||index<0||index>=items.length)return false;
 p.customItems=items.filter((_,i)=>i!==index).map(item=>item.id);return true;
}
function customItemHelp(item){return item.victoryGold?'타워 전용 · 생존 승리 시 40골드':item.help;}
function customEquipmentMarkup(p){
 const items=customEquippedItems(p),selected=TOWER_ITEMS.find(item=>item.id===customItemSelection&&!item.consumable),full=items.length>=TOWER_MAX_EQUIPMENT,stats=customEquipmentStats(p),attack=stats.dmg*stanceAttackFactor({combatStance:p.stance});
 return `<div class="custom-equipment"><div class="custom-equipment-heading"><b>아이템 <span>${items.length} / ${TOWER_MAX_EQUIPMENT}</span></b><small>무료 장착 · 자유롭게 해제</small></div><div class="custom-equipment-slots" aria-label="장착한 아이템">${Array.from({length:TOWER_MAX_EQUIPMENT},(_,index)=>{const item=items[index];return item?`<button data-custom-item-remove="${index}" aria-label="${item.name} 해제"><span>${item.icon}</span><b>${item.name}</b><i aria-hidden="true">×</i></button>`:'<div class="custom-equipment-empty"><span>＋</span><small>빈 슬롯</small></div>';}).join('')}</div><div class="equipment-stats" aria-label="아이템과 성향 적용 스탯"><span>HP <b>${stats.hp}</b></span><span>공격력 <b>${attack.toFixed(1)}</b></span><span>이동 <b>${stats.speed.toFixed(1)}</b></span>${stats.healingPower>1?`<span>주는·받는 치유 <b>+${Math.round((stats.healingPower-1)*100)}%</b></span>`:''}</div><div class="custom-item-library" role="group" aria-label="장착할 아이템 선택">${TOWER_ITEMS.filter(item=>!item.consumable).map(item=>`<button data-custom-item="${item.id}" aria-pressed="${customItemSelection===item.id}" title="${customItemHelp(item)}"><span>${item.icon}</span><b>${item.name}</b></button>`).join('')}</div><div class="custom-item-detail" role="status">${selected?`<div><b>${selected.icon} ${selected.name}</b><p>${customItemHelp(selected)}</p></div><button data-custom-item-equip="${selected.id}" class="primary" ${full?'disabled':''}>${full?'슬롯 가득 참':'장착'}</button>`:'<p>아이템을 선택하세요.</p>'}</div></div>`;
}
function renderUnitStrategy(){
 const p=roster.find(p=>p.id===strategyUnitId);if(!p)return;const stance=p.stance??'normal',custom=canEditCustomEquipment(p);
 $('unitStrategyTitle').textContent=custom?'유닛 설정':'전투 성향 부여';
 $('unitStrategyContent').innerHTML=`<div class="stance-unit">${portrait(p.type)}<div><b>${unitName(p)} #${p.id}</b><small>${p.towerAlly?'Lv.'+towerMember(p.guildId).level+' · HP '+Math.ceil(towerMember(p.guildId).hp)+' · 기력 '+towerMember(p.guildId).energy+'/5':'이 유닛에만 적용'}</small></div></div>${custom?`<div class="unit-settings-tabs" role="tablist" aria-label="유닛 설정"><button id="unitStanceTab" role="tab" aria-controls="unitSettingsPanel" data-unit-settings-tab="stance" aria-selected="${unitStrategyTab==='stance'}">행동성향</button><button id="unitItemsTab" role="tab" aria-controls="unitSettingsPanel" data-unit-settings-tab="items" aria-selected="${unitStrategyTab==='items'}">아이템</button></div>`:''}<div id="unitSettingsPanel" ${custom?'role="tabpanel" aria-labelledby="'+(unitStrategyTab==='items'?'unitItemsTab':'unitStanceTab')+'"':''}>${custom&&unitStrategyTab==='items'?customEquipmentMarkup(p):`<div class="stance-options">${Object.entries(COMBAT_STANCES).map(([id,s])=>`<button data-deploy-stance="${id}" aria-pressed="${stance===id}"><b>${s.icon} ${s.name}</b><small>${s.help}</small></button>`).join('')}</div>`}</div><button class="text-button" data-strategy-info="${p.type}">캐릭터 정보 보기 ⓘ</button>`;
}
function setDeploymentStance(id,stance){const p=roster.find(p=>p.id===id);if(!p||!COMBAT_STANCES[stance]||!['setup','towerSetup'].includes(screen)||gameKind==='tower'&&(!p.towerAlly||tower.phase!=='deploy'))return false;p.stance=stance;if(p.towerAlly)towerMember(p.guildId).stance=stance;renderRoster();return true;}
function setLiveStance(id,stance){const u=units.find(u=>u.id===id&&u.hp>0&&puppetTowerFriendly(u));if(!strategyBattleFrozen()||!u||!COMBAT_STANCES[stance])return false;u.combatStance=u.stance=stance;applyStanceStats(u);u.ai.hold=u.ai.think=0;u.ai.disengageUntil=u.ai.returnUntil=0;u.ai.response=null;u.ai.commitUntil=u.ai.punishUntil=0;u.ai.attackDecision=null;u.ai.nextInitiativeAt=elapsed+random(.2,1.1);if(stance==='cover')bindCoverAlly(u);const p=roster.find(p=>p.id===id);if(p)p.stance=stance;const member=towerMember(u.guildId);if(member)member.stance=stance;turning.selectedId=id;renderTurningPanel();return true;}
function advanceStrategyUnit(u){applyStanceStats(u);}
function strategyTarget(u,enemies,allies){
 if(u.tauntedUntil>elapsed){const target=enemies.find(e=>e.id===u.tauntedBy&&canPerceive(u,e));if(target)return target;}
 if(u.focusUntil>elapsed){const target=enemies.find(e=>e.id===u.focusTargetId&&canPerceive(u,e));if(target)return target;}
 if(u.combatStance==='cover'){let ally=allies.find(a=>a.id===u.coverAllyId);if(!ally&&u.coverAllyId!==null){bindCoverAlly(u);ally=allies.find(a=>a.id===u.coverAllyId);}const anchor=ally??u.coverAnchor;return enemies.filter(e=>canPerceive(u,e)&&dist(e,anchor)<320).sort((a,b)=>dist(a,anchor)-dist(b,anchor))[0]??null;}
 return null;
}
function strategyBlocksAttack(u){if(u.commandRetreatUntil>elapsed||u.pendingRetreat)return true;if(u.combatStance==='cover'&&u.tauntedUntil<=elapsed){const ally=units.find(a=>a.id===u.coverAllyId&&a.hp>0),target=units.find(e=>e.id===u.targetId);if(ally&&target&&dist(target,ally)>240)return true;}return false;}
function coverInterceptPosition(u,anchor,target,allies){
 let incoming=null;for(const p of projectiles){if(p.life<=0||p.source.faction===u.faction||!canSeeAttack(u,p.source,p,p.hiddenLaunch))continue;const speed=Math.hypot(p.vx,p.vy)||1,time=((anchor.x-p.x)*p.vx+(anchor.y-p.y)*p.vy)/(speed*speed);if(time<0||time>1.2||Math.hypot(p.x+p.vx*time-anchor.x,p.y+p.vy*time-anchor.y)>(p.radius??26)+28*unitScale(anchor))continue;const point={x:clamp(anchor.x-p.vx/speed*58,35,765),y:clamp(anchor.y-p.vy/speed*58,35,765)};if(!incoming||time<incoming.time)incoming={point,time,projectile:p};}
 if(incoming)return incoming;const enemy=alive().filter(e=>e.faction!==u.faction&&canPerceive(u,e)&&dist(e,anchor)<320).sort((a,b)=>dist(a,anchor)-dist(b,anchor))[0];
 if(enemy){const d=dist(enemy,anchor)||1,offset=Math.min(60,d*.45);return{point:{x:clamp(anchor.x+(enemy.x-anchor.x)/d*offset,35,765),y:clamp(anchor.y+(enemy.y-anchor.y)/d*offset,35,765)},enemy};}
 if(target&&allies.length&&allies.every(a=>a.combatStance==='cover')&&elapsed<u.ai.commitUntil){const d=dist(anchor,target)||1;return{point:{x:clamp(anchor.x+(target.x-anchor.x)/d*65,35,765),y:clamp(anchor.y+(target.y-anchor.y)/d*65,35,765)},enemy:target};}
 return{point:anchor};
}
function moveStrategy(u,target,enemies,allies,dt){
 if(u.combatStance==='cautious'&&moveRear(u,target,enemies,allies,dt))return true;
 if(u.combatStance==='cautious'&&(movePrecommit(u,target,enemies,allies,dt)||moveDefensive(u,target,enemies,allies,dt)))return true;const fleeing=u.commandRetreatUntil>elapsed,taunting=u.tauntedUntil>elapsed&&target?.id===u.tauntedBy;if(!fleeing&&!taunting&&(!u.combatStance||u.combatStance==='normal'))return false;
 if(!fleeing&&((u.type===10&&u.lostSword)||(u.type===6&&u.attack)))return false;if(!fleeing&&!taunting&&u.combatStance==='cover'&&!allies.length){if(movePrecommit(u,target,enemies,allies,dt))return true;if(u.type>=6&&u.type<=8)moveArchetype(u,target,enemies,allies,dt);else if(u.type===11)moveNovel(u,target,enemies,allies,dt);else moveGeneral(u,target,enemies,allies,dt);return true;}
 let mx=0,my=0,factor=1;const toward=(p,w=1)=>{const d=dist(u,p)||1;mx+=(p.x-u.x)/d*w;my+=(p.y-u.y)/d*w;};
 if(fleeing){if(!u.retreatPoint||dist(u,u.retreatPoint)<50||enemies.some(e=>dist(e,u.retreatPoint)<130))u.retreatPoint=safestPosition(u);toward(u.retreatPoint,1.25);factor=1.25;u.action='전략 · 안전지대 도주';}
 else if(u.combatStance==='cover'){const ally=allies.find(a=>a.id===u.coverAllyId),anchor=ally??u.coverAnchor,position=coverInterceptPosition(u,anchor,target,allies);toward(position.point,dist(u,position.point)>18?1:.12);u.action=position.projectile?'전략 · 아군 앞 탄도 차단':position.enemy?'전략 · 적과 아군 사이 엄호':'전략 · 아군 따라붙기';}
 else if(target){const d=dist(u,target),dx=(target.x-u.x)/(d||1),dy=(target.y-u.y)/(d||1),side=u.ai.side,sway=Math.sin(elapsed*3+u.phase)*.35;
 const reloading=u.type===7&&u.reloadRemaining>0;
 if((u.combatStance==='rush'||taunting)&&!reloading){const desired=u.range>100?Math.min(110,u.range*.5):u.range*.65,radial=d>desired?1:.12;mx=dx*radial-dy*(side*.25+sway);my=dy*radial+dx*(side*.25+sway);u.ai.disengageUntil=u.ai.returnUntil=0;u.ai.mode='approach';u.action='전략 · 저돌적 진입';factor=1.07;}
 else{const opening=u.cooldown<=0&&(elapsed<u.ai.commitUntil||elapsed<u.ai.punishUntil);const desired=reloading?330:opening?u.range*.75:Math.max(155,u.range*.98),radial=clamp((d-desired)/95,-1,1);mx=dx*radial-dy*side*.6;my=dy*radial+dx*side*.6;u.action=reloading?'장전 중 거리 확보':'전략 · 신중한 거리 조절';}
 }else{toward(u.ai.goal,.45);u.action='전략 · 주변 탐색';}
 if(!fleeing&&u.combatStance!=='cover'){const incoming=projectileThreat(u);if(incoming&&!u.attack&&incoming.time<u.ai.reaction*(u.combatStance==='cautious'?1.35:u.combatStance==='rush'?.65:1)){const p=incoming.p,len=Math.hypot(p.vx,p.vy)||1,nx=-p.vy/len,ny=p.vx/len,side=Math.sign((u.x-p.x)*nx+(u.y-p.y)*ny)||u.ai.side;mx=mx*.2+nx*side;my=my*.2+ny*side;factor=1.12;u.action='전략 · 탄도 회피';}}
 if(u.attack)factor*=u.attack.phase==='windup'?.25:.5;
 for(const v of [...allies,...enemies]){const d=dist(u,v);if(d<55){const a=Math.atan2(u.y-v.y,u.x-v.x);mx+=Math.cos(a)*(55-d)/22;my+=Math.sin(a)*(55-d)/22;}}
 if(u.x<55)mx+=(55-u.x)/30;if(u.x>745)mx-=(u.x-745)/30;if(u.y<55)my+=(55-u.y)/30;if(u.y>745)my-=(u.y-745)/30;const len=Math.hypot(mx,my)||1;if(len>1){mx/=len;my/=len;}blendHeading(u,mx,my,dt,9);const ox=u.x,oy=u.y;u.x=clamp(u.x+u.headingX*u.moveSpeed*movementRate(u)*factor*dt,28,772);u.y=clamp(u.y+u.headingY*u.moveSpeed*movementRate(u)*factor*dt,28,772);u.vx=(u.x-ox)/dt;u.vy=(u.y-oy)/dt;return true;
}
function strategyCardStatus(copy){if(!copy)return{ready:false,label:'카드 없음'};const card=STRATEGY_CARDS.find(c=>c.kind===copy.kind);if(!card)return{ready:false,label:'카드 없음'};if(card.usage==='floor'&&(copy.usedDepth===tower.floor||copy.usedFloors?.includes(tower.floor)))return{ready:false,label:'이번 층 사용 완료'};if(card.usage==='cooldown'&&tower.unlockedFloor<(copy.readyFloor??0))return{ready:false,label:(copy.readyFloor+1)+'층부터 사용'};return{ready:true,label:card.rule};}
function giveStrategyCard(kind){if(!tower||!STRATEGY_CARDS.some(c=>c.kind===kind))return false;const copy={id:tower.nextStrategyCardId++,kind,usedDepth:null,readyFloor:0};tower.strategyCards.push(copy);return copy;}
function buyStrategyCard(kind,copyIndex){const card=STRATEGY_CARDS.find(c=>c.kind===kind),offer=towerShopOffers('card').find(o=>o.kind===kind);if(tower?.phase!=='shop'||!card||!offer||tower.gold<card.cost)return false;const index=availableTowerShopCopy(offer,copyIndex);if(index<0)return false;spendTowerResources(card.cost,0,'[data-strategy-buy="'+kind+'"][data-shop-copy="'+index+'"]');offer.purchasedCopies[index]=true;offer.quantity--;giveStrategyCard(kind);renderTower();towerMessage(card.name+' 전략카드 구매 완료');return true;}
function strategyShopMarkup(){return `<div class="strategy-shop-cards">${towerShopOffers('card').flatMap(offer=>{const c=STRATEGY_CARDS.find(c=>c.kind===offer.kind);return towerShopCopies(offer).map(copy=>`<button data-strategy-buy="${c.kind}" data-shop-copy="${copy.index}" class="${copy.purchased?'shop-purchased':''}" ${copy.purchased||tower.gold<c.cost?'disabled':''}><span>${c.icon}</span><b>${c.name}</b><small>${c.help}</small><em>${c.rule}</em><strong class="shop-price">${copy.purchased?'구매 완료':'🪙 '+c.cost+'G'}</strong></button>`);}).join('')}</div>`;}
function strategyInventorySlots(){return tower.strategyCards.map(copy=>{const card=STRATEGY_CARDS.find(c=>c.kind===copy.kind),status=strategyCardStatus(copy);return `<button class="inventory-slot inventory-strategy ${status.ready?'':'card-unavailable'}" data-inventory-card="${copy.id}" aria-label="전략카드 ${card.name} · ${card.help} · ${status.label}" title="${card.help} · ${status.label}"><i>전략</i><span>${card.icon}</span><small>${card.name}</small><em>${status.ready?card.usage==='once'?'일회성':card.usage==='floor'?'층당 1회':'두 층 쿨타임':status.label}</em></button>`;});}
function openStrategyCardInfo(id){const copy=tower?.strategyCards.find(c=>c.id===id),card=STRATEGY_CARDS.find(c=>c.kind===copy?.kind);if(!card)return false;const status=strategyCardStatus(copy);$('characterInfoContent').innerHTML=`<div class="info-header"><span class="inventory-card-icon" aria-hidden="true">${card.icon}</span><div><h2>${card.name}</h2><p>특수전략카드 · ${card.rule}</p></div></div><dl><dt>효과</dt><dd>${card.help}</dd><dt>사용 상태</dt><dd>${status.ready?'사용 가능 · ':''}${status.label}</dd><dt>사용 방법</dt><dd>전투 중 터닝포인트에서 생존 아군에게 드래그하거나, 카드를 선택한 뒤 아군을 터치하세요.</dd></dl>`;$('characterInfo').showModal();return true;}
function strategyBattleActive(){return turning.enabled&&['brake','hold'].includes(turning.phase);}
function strategyBattleFrozen(){return turning.enabled&&turning.phase==='hold'&&running&&screen==='battle'&&tower?.phase==='battle';}
function resetTurningPoint(interactive){closeTurningPoint();turning={enabled:gameKind==='tower'&&interactive,phase:'idle',nextAt:TURNING_FIRST,brake:0,remaining:0,selectedId:null,selectedCard:null,forecasts:[],serial:0};}
function startTurningPoint(){if(!turning.enabled||turning.phase!=='idle'||!running||gameKind!=='tower'||tower.phase!=='battle'||new Set(alive().map(u=>u.faction)).size<2)return false;turning.phase='brake';turning.brake=0;turning.nextAt+=TURNING_INTERVAL;turning.serial++;$('turningNotice').hidden=false;$('battleScreen').dataset.turning='brake';setTurningControls(true);return true;}
function setTurningControls(disabled){$('pause').disabled=disabled;$('showStatus').disabled=disabled;for(const b of document.querySelectorAll('[data-speed]'))b.disabled=disabled;}
function holdTurningPoint(){turning.phase='hold';turning.remaining=TURNING_DURATION;turning.selectedId=units.find(u=>puppetTowerFriendly(u)&&u.hp>0)?.id??null;turning.selectedCard=null;turning.forecasts=buildEnemyForecasts();accumulator=0;cinema.anticipation=0;cinema.zoom=1;cinema.x=cinema.y=400;cameraShake=shakeX=shakeY=0;$('turningNotice').hidden=true;$('battleScreen').dataset.turning='hold';if($('battleDetails').open)$('battleDetails').close();renderTurningPanel();}
function advanceTurningPoint(dt){if(typeof transcendenceFrozen==='function'&&transcendenceFrozen())return strategyBattleFrozen();if(!turning.enabled||screen!=='battle'||!running||tower?.phase!=='battle')return false;if(turning.phase==='idle'&&!paused&&cinema.intro<=0&&elapsed>=turning.nextAt)startTurningPoint();if(turning.phase==='brake'){turning.brake+=dt;if(turning.brake>=TURNING_BRAKE){const extra=turning.brake-TURNING_BRAKE;holdTurningPoint();turning.remaining=Math.max(0,TURNING_DURATION-extra);if(!turning.remaining)resumeTurningPoint();else updateTurningClock();return strategyBattleFrozen();}return false;}if(turning.phase==='hold'){turning.remaining=Math.max(0,turning.remaining-dt);updateTurningClock();if(!turning.remaining){resumeTurningPoint();return false;}return true;}return false;}
function turningPointScale(){return turning.phase==='brake'?Math.max(.035,1-turning.brake/TURNING_BRAKE):turning.phase==='hold'?0:1;}
function updateTurningClock(){const clock=$('turningClock');if(clock)clock.textContent=Math.ceil(turning.remaining)+'초';}
function buildEnemyForecasts(){const allies=units.filter(u=>u.faction==='team:0'&&u.hp>0);return units.filter(u=>u.faction==='team:1'&&u.hp>0).map(enemy=>{const target=allies.find(u=>u.type===5)??allies.slice().sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];let kind=['special','focus','retreat'][Math.floor(Math.random()*3)];if(kind==='focus'&&!target)kind='retreat';return{enemyId:enemy.id,kind,targetId:target?.id,label:kind==='special'?'특수 능력 사용 직전':kind==='focus'?'목표 변경: '+TYPES[target.type].name:'후퇴'};});}
function cancelStrategyIntent(u){u.ai.response=null;u.ai.commitUntil=u.ai.punishUntil=0;u.ai.attackDecision=null;const duel=duelFor(u);if(duel)cancelDuel(duel);u.attack=u.ultCast=null;u.dodgeState=u.strategyDash=null;u.evadeTime=0;for(const s of meleeStrikes)if(s.source.id===u.id)s.life=0;effects=effects.filter(e=>e.unitId!==u.id&&e.ownerId!==u.id);u.kx=u.ky=0;u.headingX=u.headingY=0;u.guardRemaining=0;}
function orderStrategyRetreat(u){cancelStrategyIntent(u);u.pendingRetreat=false;u.commandRetreatUntil=elapsed+6;u.retreatPoint=safestPosition(u);u.ai.disengageUntil=0;startStrategyEscapeDash(u);}
function applyEnemyForecasts(){for(const plan of turning.forecasts){const u=units.find(v=>v.id===plan.enemyId&&v.hp>0);if(!u||u.faction!=='team:1')continue;if(plan.kind==='retreat')orderStrategyRetreat(u);if(plan.kind==='focus'){cancelStrategyIntent(u);u.focusTargetId=plan.targetId;u.focusUntil=elapsed+10;u.targetClock=0;}if(plan.kind==='special'){cancelStrategyIntent(u);if(ULTIMATES[u.type]){gainUltimate(u,100);u.ultThink=0;u.ultReadyAge=5;u.strategyUltimateReady=true;}else{u.strategySpecialUntil=elapsed+8;u.cooldown=0;if(u.type===7){u.ammo=2;u.reloadRemaining=0;}}applyStanceStats(u);}}}
function resumeTurningPoint(){if(typeof transcendenceFrozen==='function'&&transcendenceFrozen())return false;if(!strategyBattleFrozen())return false;applyEnemyForecasts();for(const u of units.filter(v=>puppetTowerFriendly(v)&&v.hp>0)){if(u.pendingRetreat)orderStrategyRetreat(u);for(const id of u.pendingTauntIds??[]){const enemy=units.find(v=>v.id===id&&v.hp>0);if(!enemy)continue;cancelStrategyIntent(enemy);enemy.commandRetreatUntil=0;enemy.tauntedBy=u.id;enemy.tauntedUntil=elapsed+8;enemy.targetId=u.id;enemy.targetClock=0;}u.pendingTauntIds=[];}turning.phase='idle';turning.remaining=0;turning.selectedCard=null;accumulator=0;paused=false;$('turningPanel').hidden=true;delete $('battleScreen').dataset.turning;setTurningControls(false);setPauseLabel();return true;}
function closeTurningPoint(){if(typeof turning==='undefined')return;turning.enabled=false;turning.phase='idle';strategyDrag=null;$('turningPanel').hidden=true;$('turningNotice').hidden=true;$('showStatus').disabled=false;delete $('battleScreen').dataset.turning;$('strategyDragGhost')?.remove?.();for(const b of document.querySelectorAll('[data-speed]'))b.disabled=false;}
function applyStrategyCard(id,unitId){if(!strategyBattleFrozen())return false;const u=units.find(v=>v.id===unitId&&v.hp>0&&puppetTowerFriendly(v)),copy=tower.strategyCards.find(c=>c.id===id),card=STRATEGY_CARDS.find(c=>c.kind===copy?.kind);if(!u||!card||!strategyCardStatus(copy).ready)return false;
 if(card.kind==='mango'){if(u.hp>=u.maxHp)return false;restoreCombatHp(u,u.maxHp*.3,null);}
 if(card.kind==='shield'){u.shieldHp=100;u.shieldTime=8;fx('barrierGain',u.x,u.y,'#9bddeb',.35,{unitId:u.id,r:48});}
 if(card.kind==='iron'){u.ironDefenseTime=15;u.parryCooldown=0;if(u.type===0)u.defenseCooldown=0;fx('barrierGain',u.x,u.y,'#dce9b2',.35,{unitId:u.id,r:48});}
 if(card.kind==='charge'){if(gainUltimate(u,50)<=0)return false;}
 if(card.kind==='evade'){if(u.pendingRetreat)return false;u.pendingRetreat=true;}
 if(card.kind==='taunt'){if(u.pendingTauntIds?.length)return false;const enemies=units.filter(v=>v.faction==='team:1'&&v.hp>0&&canPerceive(v,u)).sort((a,b)=>dist(u,a)-dist(u,b)).slice(0,2);if(!enemies.length)return false;u.pendingTauntIds=enemies.map(v=>v.id);}
 if(card.usage==='once')tower.strategyCards=tower.strategyCards.filter(c=>c.id!==id);else if(card.usage==='floor'){copy.usedDepth=tower.floor;(copy.usedFloors??=[]).push(tower.floor);}else copy.readyFloor=tower.unlockedFloor+3;turning.selectedId=u.id;turning.selectedCard=null;renderTurningPanel(card.name+' 적용');updateStats();draw();return true;
}
function renderTurningPanel(message=''){
 const selected=units.find(u=>u.id===turning.selectedId&&u.hp>0&&puppetTowerFriendly(u));if(!selected)turning.selectedId=null;
 const selectedCard=STRATEGY_CARDS.find(c=>c.kind===tower.strategyCards.find(copy=>copy.id===turning.selectedCard)?.kind),note=message||(selectedCard?selectedCard.name+' · '+selectedCard.help:'');
 const cards=tower.strategyCards.map(copy=>{const c=STRATEGY_CARDS.find(c=>c.kind===copy.kind),status=strategyCardStatus(copy);return `<button class="strategy-card ${turning.selectedCard===copy.id?'selected':''}" data-turn-card="${copy.id}" ${!status.ready?'disabled':''} aria-pressed="${turning.selectedCard===copy.id}" title="${c.help} · ${status.label}" aria-label="${c.name} · ${c.help} · ${status.label}"><span>${c.icon}</span><b>${c.name}</b><small>${status.ready?c.help:status.label}</small><em>${c.usage==='once'?'일회성':c.usage==='floor'?'층당 1회':'두 층 쿨타임'}</em></button>`;}).join('');
 $('turningPanel').hidden=false;$('turningPanel').innerHTML=`<div class="turning-title"><h2>터닝포인트 <span id="turningClock">${Math.ceil(turning.remaining)}초</span></h2><button id="resumeStrategy" class="secondary">전투 재개 ▶</button></div><div class="turning-selection"><b>${selected?EMOJIS[selected.type]+' '+TYPES[selected.type].name:'맵의 생존 아군을 터치하세요'}</b><span>${selected?'HP '+Math.ceil(selected.hp)+' / '+selected.maxHp+' · 궁극기 '+Math.floor(selected.ultGauge)+'%'+(selected.shieldHp>0?' · 보호막 '+Math.ceil(selected.shieldHp):'')+(selected.ironDefenseTime>0?' · 철벽방어 '+Math.ceil(selected.ironDefenseTime)+'초':''):''}</span></div><div class="turning-stances">${selected?stanceButtons(selected.combatStance,'data-live-stance'):''}</div><p id="strategyMessage" class="strategy-message" role="status" ${note?'':'hidden'}>${note}</p><div class="turning-cards" role="group" aria-label="특수전략카드">${cards||'<p>보유 전략카드 없음</p>'}</div>`;
 if(typeof fitTurningArena==='function')fitTurningArena();
}
function showStrategyMessage(message){const el=$('strategyMessage');el.textContent=message;el.hidden=false;if(typeof fitTurningArena==='function')fitTurningArena();}
function strategyCanvasUnit(clientX,clientY){const rect=$('arena').getBoundingClientRect();if(clientX<rect.left||clientX>rect.right||clientY<rect.top||clientY>rect.bottom)return null;const x=((clientX-rect.left)/rect.width*800-400)/cinema.zoom+cinema.x-shakeX,y=((clientY-rect.top)/rect.height*800-400)/cinema.zoom+cinema.y-shakeY;return units.filter(u=>puppetTowerFriendly(u)&&u.hp>0).map(u=>({u,d:Math.hypot(x-u.x,y-u.y)})).sort((a,b)=>a.d-b.d).find(({u,d})=>d<Math.max(25*unitScale(u),18/rect.width*800))?.u??null;}
function renderStrategySelection(){if(!strategyBattleFrozen())return;const u=units.find(v=>v.id===turning.selectedId&&v.hp>0);if(u)circle(u.x,u.y,34*unitScale(u),'#ffde9c',false,3);}
$('closeUnitStrategy').onclick=()=>$('unitStrategy').close();
// A touch opening the dialog must not activate a new button under the same finger.
const UNIT_SETTINGS_ACTIONS='[data-deploy-stance],[data-strategy-info],[data-unit-settings-tab],[data-custom-item],[data-custom-item-equip],[data-custom-item-remove]';
$('unitStrategyContent').addEventListener('pointerdown',e=>{deploymentStrategyPress=e.isPrimary!==false&&e.button===0?e.target.closest(UNIT_SETTINGS_ACTIONS):null;});
$('unitStrategyContent').addEventListener('pointercancel',()=>{deploymentStrategyPress=null;});
$('unitStrategyContent').addEventListener('click',e=>{const pressed=deploymentStrategyPress;deploymentStrategyPress=null;if(e.detail>0&&pressed!==e.target.closest(UNIT_SETTINGS_ACTIONS)){e.preventDefault();return;}const p=roster.find(p=>p.id===strategyUnitId);
 const tab=e.target.closest('[data-unit-settings-tab]');if(tab&&canEditCustomEquipment(p)&&['stance','items'].includes(tab.dataset.unitSettingsTab)){unitStrategyTab=tab.dataset.unitSettingsTab;renderUnitStrategy();$(unitStrategyTab==='items'?'unitItemsTab':'unitStanceTab').focus();return;}
 const item=e.target.closest('[data-custom-item]');if(item&&canEditCustomEquipment(p)){customItemSelection=item.dataset.customItem;renderUnitStrategy();document.querySelector?.('[data-custom-item="'+customItemSelection+'"]')?.focus();return;}
 const equip=e.target.closest('[data-custom-item-equip]');if(equip&&equipCustomItem(strategyUnitId,equip.dataset.customItemEquip)){renderUnitStrategy();return;}
 const remove=e.target.closest('[data-custom-item-remove]');if(remove&&removeCustomItem(strategyUnitId,+remove.dataset.customItemRemove)){renderUnitStrategy();return;}
 const stance=e.target.closest('[data-deploy-stance]');if(stance&&setDeploymentStance(strategyUnitId,stance.dataset.deployStance)){renderUnitStrategy();return;}const info=e.target.closest('[data-strategy-info]');if(info){$('unitStrategy').close();const p=roster.find(p=>p.id===strategyUnitId);openCharacterInfo(+info.dataset.strategyInfo,p);}});
function handleStrategyUnit(x,y){if(!strategyBattleFrozen())return;const u=strategyCanvasUnit(x,y);if(!u)return;if(turning.selectedCard!==null){if(!applyStrategyCard(turning.selectedCard,u.id))showStrategyMessage('적용할 수 없습니다. HP·궁극기·카드 조건을 확인하세요.');return;}turning.selectedId=u.id;renderTurningPanel();}
function selectTurningCard(id){const copy=tower.strategyCards.find(c=>c.id===id);if(!strategyBattleFrozen()||!strategyCardStatus(copy).ready)return;turning.selectedCard=turning.selectedCard===id?null:id;renderTurningPanel();}
function handleTurningPanel(e){if(!strategyBattleFrozen()||Date.now()<suppressStrategyClickUntil)return;if(e.target.closest('#resumeStrategy')){resumeTurningPoint();return;}const stance=e.target.closest('[data-live-stance]');if(stance){setLiveStance(turning.selectedId,stance.dataset.liveStance);return;}const card=e.target.closest('[data-turn-card]');if(card&&!card.disabled)selectTurningCard(+card.dataset.turnCard);}
function rememberStrategyTouch(e){strategyTouch={time:Date.now(),x:e.clientX,y:e.clientY};}
function strategySyntheticTouch(e){return e.pointerType==='touch'||e.sourceCapabilities?.firesTouchEvents||e.detail>0&&strategyTouch&&Date.now()-strategyTouch.time<700&&Math.hypot(e.clientX-strategyTouch.x,e.clientY-strategyTouch.y)<5;}
$('arena').addEventListener('click',e=>{if(!strategySyntheticTouch(e))handleStrategyUnit(e.clientX,e.clientY);});
$('arena').addEventListener('pointerup',e=>{if(e.pointerType==='touch'&&!strategyDrag){rememberStrategyTouch(e);handleStrategyUnit(e.clientX,e.clientY);}});
$('turningPanel').addEventListener('click',e=>{if(!strategySyntheticTouch(e))handleTurningPanel(e);});
$('turningPanel').addEventListener('pointerup',e=>{if(e.pointerType==='touch'&&!strategyDrag){rememberStrategyTouch(e);handleTurningPanel(e);}});
$('turningPanel').addEventListener('pointerdown',e=>{const card=e.target.closest('[data-turn-card]');if(!strategyBattleFrozen()||!card||card.disabled||e.button!==0)return;strategyDrag={id:+card.dataset.turnCard,pointer:e.pointerId,x:e.clientX,y:e.clientY,moved:false};card.setPointerCapture?.(e.pointerId);});
window.addEventListener('pointermove',e=>{if(!strategyDrag||e.pointerId!==strategyDrag.pointer)return;if(Math.hypot(e.clientX-strategyDrag.x,e.clientY-strategyDrag.y)>8)strategyDrag.moved=true;if(!strategyDrag.moved)return;e.preventDefault();let ghost=document.getElementById('strategyDragGhost');if(!ghost){ghost=document.createElement('div');ghost.id='strategyDragGhost';ghost.className='strategy-drag-ghost';document.body.appendChild(ghost);}const copy=tower.strategyCards.find(c=>c.id===strategyDrag.id),card=STRATEGY_CARDS.find(c=>c.kind===copy?.kind);ghost.textContent=card?.icon??'';ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';},{passive:false});
window.addEventListener('pointerup',e=>{if(!strategyDrag||e.pointerId!==strategyDrag.pointer)return;const drag=strategyDrag;if(e.pointerType==='touch')rememberStrategyTouch(e);strategyDrag=null;document.getElementById('strategyDragGhost')?.remove();if(!drag.moved){if(e.pointerType==='touch')selectTurningCard(drag.id);return;}suppressStrategyClickUntil=Date.now()+400;const u=strategyCanvasUnit(e.clientX,e.clientY);if(!u||!applyStrategyCard(drag.id,u.id))showStrategyMessage('카드를 생존 아군 위에 놓으세요. 사용 조건을 확인하세요.');});
window.addEventListener('pointercancel',()=>{strategyDrag=null;document.getElementById('strategyDragGhost')?.remove();});
$('towerBody').addEventListener('click',e=>{const buy=e.target.closest('[data-strategy-buy]');if(buy)buyStrategyCard(buy.dataset.strategyBuy,+buy.dataset.shopCopy);});
function startStrategyEscapeDash(u){const enemies=alive().filter(v=>v.faction!==u.faction),safe=u.retreatPoint??safestPosition(u),candidates=[];for(let i=0;i<16;i++){const a=i*Math.PI/8,point={x:clamp(u.x+Math.cos(a)*260,35,765),y:clamp(u.y+Math.sin(a)*260,35,765)},distance=dist(u,point);if(distance<80)continue;const clearance=enemies.length?Math.min(...enemies.map(e=>dist(e,point))):300,route=alive().filter(v=>v.id!==u.id&&distanceToSegment(v,u,point)<27*(unitScale(v)+unitScale(u))).length;candidates.push({point,score:clearance-route*55-dist(point,safe)*.2});}candidates.sort((a,b)=>b.score-a.score);const point=candidates[0]?.point??safe,distance=dist(u,point)||1;u.strategyDash={direction:{x:(point.x-u.x)/distance,y:(point.y-u.y)/distance},remaining:distance,speed:720,trailClock:0};u.dodgeState=null;u.evadeTime=0;u.headingX=u.headingY=u.vx=u.vy=0;u.action='전투회피 · 탈출 대시';}
function advanceStrategyDash(u,dt){const dash=u.strategyDash;if(!dash)return false;if(u.hp<=0||u.stun>0||duelLocked(u)||novelLocked(u)){u.strategyDash=null;u.headingX=u.headingY=0;return false;}const before={x:u.x,y:u.y},distance=Math.min(dash.remaining,dash.speed*dt);u.x=clamp(u.x+dash.direction.x*distance,28,772);u.y=clamp(u.y+dash.direction.y*distance,28,772);dash.remaining-=dist(before,u);u.vx=(u.x-before.x)/dt;u.vy=(u.y-before.y)/dt;u.face=Math.atan2(dash.direction.y,dash.direction.x);u.headingX=u.headingY=0;u.action='전투회피 · 탈출 대시';dash.trailClock+=dt;if(dash.trailClock>=.025){dash.trailClock=0;fx('afterimage',before.x,before.y,'#cceaf0',.1,{tx:u.x,ty:u.y,type:u.type,ownerId:u.id});}if(dash.remaining<1||dist(before,u)<.01)u.strategyDash=null;return true;}
